<?php use App\Domain\Transfers\TransferRules as Rules; $t=$transfer; ?>
<section class="admin-page-head"><div><p class="admin-kicker">M09 · <?= e(Rules::LABELS[$t['status']]) ?></p><h1><?= e($t['folio']) ?></h1><p><?= e($t['source_name']) ?> → <?= e($t['destination_name']) ?></p></div><a class="admin-secondary-button" href="/admin/transfers">Transferencias</a></section>
<section class="admin-panel"><p><?= e($t['reason']) ?></p><p>Versión de concurrencia: <?= e($t['lock_version']) ?> · Cotización / versión: <?= e($t['quote_version_id']??'Sin relación') ?> · <?= e($t['created_at']) ?> UTC</p><p>El pendiente en tránsito permanece trazable. Las incidencias no registran pérdidas ni entradas automáticas.</p></section>
<section class="admin-panel admin-table-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Mercancía</th><th>Solicitada</th><th>Autorizada</th><th>Despachada</th><th>Recibida</th><th>Por despachar</th><th>En tránsito</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td data-label="Mercancía"><?= e($i['sku'].' · '.$i['product_name'].' ('.$i['symbol'].')') ?></td><?php foreach(['requested_quantity'=>'Solicitada','approved_quantity'=>'Autorizada','dispatched_quantity'=>'Despachada','received_quantity'=>'Recibida','pending_dispatch'=>'Por despachar','in_transit'=>'En tránsito']as $k=>$label):?><td data-label="<?= e($label) ?>"><?= e($i[$k]) ?></td><?php endforeach?></tr><?php endforeach?></tbody></table></div></section>
<?php $labels=['edit'=>'Editar cantidades solicitadas','approve'=>'Aprobar y apartar en origen','prepare'=>'Confirmar mercancía preparada','dispatch'=>'Confirmar salida física de origen','receive'=>'Confirmar recepción física en destino','cancel'=>'Cancelar y liberar apartado de origen','incident'=>'Registrar incidencia'];foreach($labels as $action=>$label):if(!$actions[$action])continue;if($action==='dispatch'&&!array_filter($items,fn($i)=>\App\Domain\Pricing\Decimal::parse($i['pending_dispatch'],6)->compare(\App\Domain\Pricing\Decimal::zero(6))>0))continue;if($action==='receive'&&!array_filter($items,fn($i)=>\App\Domain\Pricing\Decimal::parse($i['in_transit'],6)->compare(\App\Domain\Pricing\Decimal::zero(6))>0))continue;try{Rules::transition($t['status'],$action);}catch(Throwable){continue;} ?>
<section class="admin-panel"><h2><?= e($label) ?></h2><form method="post" action="/admin/transfers/action" data-transfer-event <?= in_array($action,['dispatch','receive','cancel'],true)?'data-transfer-confirm':'' ?>>
<input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= e($t['id']) ?>"><input type="hidden" name="lock_version" value="<?= e($t['lock_version']) ?>"><input type="hidden" name="action" value="<?= e($action) ?>"><input type="hidden" name="operation_key" value="<?= e(bin2hex(random_bytes(20))) ?>">
<?php if(in_array($action,['edit','approve','dispatch','receive'],true)):?><div class="admin-form-grid"><?php foreach($items as $i): $pending=match($action){'edit','approve'=>$i['requested_quantity'],'dispatch'=>$i['pending_dispatch'],default=>$i['in_transit']};?><label class="admin-field"><span><?= e($i['sku'].' · '.$i['symbol']) ?> · <?= e($action==='edit'?'Actual':'Máximo') ?> <?= e($pending) ?></span><input name="quantity[<?= e($i['id']) ?>]" inputmode="decimal" value="<?= e($action==='edit'?$pending:'0') ?>"></label><?php endforeach?></div><?php endif?>
<label class="admin-field"><span>Observaciones <?= in_array($action,['incident','cancel'],true)?'(obligatorias)':'' ?></span><textarea name="notes" maxlength="500" <?= in_array($action,['incident','cancel'],true)?'required minlength="5"':'' ?>></textarea></label>
<?php if(in_array($action,['dispatch','receive','cancel'],true)):?><label><input type="checkbox" required> Confirmo las cantidades y la operación <?= e($action==='dispatch'?'de salida física':($action==='receive'?'de recepción física':'de cancelación')) ?>.</label><?php endif?><button type="submit" class="admin-primary-button"><?= e($label) ?></button></form></section><?php endforeach?>
<?php if($history):?><section class="admin-panel"><h2>Historial y movimientos M05</h2><ol><?php foreach($history as $h):?><li><strong><?= e(($labels+['create'=>'Solicitud creada'])[$h['action']]??$h['action']) ?></strong> · <?= e($h['actor_name']) ?> · <?= e($h['created_at']) ?> UTC<p><?= e($h['notes']) ?> <?= e($h['quantity']??'') ?><?php if($h['inventory_movement_id']):?> · Movimiento M05 #<?= e($h['inventory_movement_id']) ?><?php endif?></p></li><?php endforeach?></ol></section><?php endif?>
